package pathstudy

//gooo:generated:start id="pathstudy://activity/conditional-assign" kind="activity"
func ConditionalAssign(input int64) int64 {
	var left = (input + 5)
	var right = (input - 10)
	var guard = (0 < input)
	var guard_alt = (input <= 5)
	guard = (guard && guard_alt)
	if guard {
		left = (input - 10)
	} else {
		right = (input + 5)
	}
	return (left + right)
}

//gooo:generated:end id="pathstudy://activity/conditional-assign" kind="activity"
